import type { EntityDef, GameBake, GameManifest, SpawnDef } from "../manifest.ts";

export type InputState = {
  forward: number;
  strafe: number;
  mouseDx: number;
  mouseDy: number;
  keys: Set<string>;
  consumeKey(code: string): boolean;
};

export function createInput(canvas: HTMLCanvasElement): InputState & { dispose: () => void } {
  const keys = new Set<string>();
  let mouseDx = 0;
  let mouseDy = 0;
  const down = (e: KeyboardEvent) => {
    keys.add(e.code);
    if (["Space", "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(e.code)) {
      e.preventDefault();
    }
  };
  const up = (e: KeyboardEvent) => keys.delete(e.code);
  const move = (e: MouseEvent) => {
    if (document.pointerLockElement === canvas) {
      mouseDx += e.movementX;
      mouseDy += e.movementY;
    }
  };
  const mouseDown = (e: MouseEvent) => {
    keys.add(`Mouse${e.button}`);
  };
  const mouseUp = (e: MouseEvent) => {
    keys.delete(`Mouse${e.button}`);
  };
  const click = () => {
    if (document.pointerLockElement !== canvas) canvas.requestPointerLock();
  };
  window.addEventListener("keydown", down);
  window.addEventListener("keyup", up);
  window.addEventListener("mousemove", move);
  window.addEventListener("mousedown", mouseDown);
  window.addEventListener("mouseup", mouseUp);
  canvas.addEventListener("click", click);

  const state = {
    keys,
    get forward() {
      let v = 0;
      if (keys.has("KeyW") || keys.has("ArrowUp")) v += 1;
      if (keys.has("KeyS") || keys.has("ArrowDown")) v -= 1;
      return v;
    },
    get strafe() {
      let v = 0;
      if (keys.has("KeyD") || keys.has("ArrowRight")) v += 1;
      if (keys.has("KeyA") || keys.has("ArrowLeft")) v -= 1;
      return v;
    },
    get mouseDx() {
      const v = mouseDx;
      mouseDx = 0;
      return v;
    },
    get mouseDy() {
      const v = mouseDy;
      mouseDy = 0;
      return v;
    },
    consumeKey(code: string) {
      if (!keys.has(code)) return false;
      keys.delete(code);
      return true;
    },
    dispose() {
      window.removeEventListener("keydown", down);
      window.removeEventListener("keyup", up);
      window.removeEventListener("mousemove", move);
      window.removeEventListener("mousedown", mouseDown);
      window.removeEventListener("mouseup", mouseUp);
      canvas.removeEventListener("click", click);
    },
  };
  return state;
}

export class PrefabRegistry {
  constructor(private readonly prefabs: Record<string, EntityDef>) {}

  get(name: string): EntityDef | null {
    return this.prefabs[name] ?? null;
  }

  names(): string[] {
    return Object.keys(this.prefabs);
  }
}

export type SavePayload = {
  slot: string;
  modeId?: string;
  pawn?: unknown;
  attributes?: unknown;
  revision?: number;
  score?: number;
};

export class SaveClient {
  async list(): Promise<unknown[]> {
    const res = await fetch("/api/saves");
    if (!res.ok) return [];
    return res.json();
  }

  async put(payload: SavePayload): Promise<{ ok: boolean; id?: string }> {
    const res = await fetch("/api/saves", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        id: payload.slot,
        data: payload,
      }),
    });
    return res.json();
  }

  async get(slot: string): Promise<SavePayload | null> {
    const rows = (await this.list()) as Array<{ id: string; data: SavePayload }>;
    const row = rows.find((r) => r.id === slot);
    return row?.data ?? null;
  }
}

export class TelemetryClient {
  async event(kind: string, payload: unknown = {}): Promise<void> {
    await fetch("/api/telemetry", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ kind, payload }),
    }).catch(() => undefined);
  }
}

export class RunClient {
  private runId: string | null = null;

  async start(modeId: string): Promise<{ runId: string; seed: number }> {
    const res = await fetch("/api/runs/start", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ modeId }),
    });
    const body = (await res.json()) as { runId: string; seed: number };
    this.runId = body.runId;
    return body;
  }

  async end(outcome: "win" | "lose" | "quit"): Promise<void> {
    if (!this.runId) return;
    await fetch("/api/runs/end", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ runId: this.runId, outcome }),
    }).catch(() => undefined);
    this.runId = null;
  }

  get currentRunId(): string | null {
    return this.runId;
  }
}

export type Resources = {
  manifest: GameManifest;
  bake: GameBake;
  prefabs: PrefabRegistry;
  input: InputState & { dispose: () => void };
  save: SaveClient;
  telemetry: TelemetryClient;
  run: RunClient;
  data: Record<string, Record<string, unknown>>;
  kit: import("../adapters/kitBuilder.ts").KitDef | null;
  kitMaterials: Record<string, import("../adapters/kitBuilder.ts").MaterialDef>;
};

export function buildResources(
  manifest: GameManifest,
  bake: GameBake,
  canvas: HTMLCanvasElement,
  kit?: import("../adapters/kitBuilder.ts").KitDef | null,
  kitMaterials?: Record<string, import("../adapters/kitBuilder.ts").MaterialDef>,
): Resources {
  const prefabSource = Object.keys(bake.prefabs || {}).length
    ? bake.prefabs
    : manifest.prefabs;
  const data = Object.keys(bake.data || {}).length ? bake.data : manifest.data;
  const mats =
    kitMaterials ??
    (bake.materials as Record<string, import("../adapters/kitBuilder.ts").MaterialDef>) ??
    {};
  return {
    manifest,
    bake,
    prefabs: new PrefabRegistry(prefabSource),
    input: createInput(canvas),
    save: new SaveClient(),
    telemetry: new TelemetryClient(),
    run: new RunClient(),
    data,
    kit: kit ?? (bake as GameBake & { kit?: import("../adapters/kitBuilder.ts").KitDef }).kit ?? null,
    kitMaterials: mats,
  };
}

